class BankAccount {
    protected String accountNumber;
    protected double balance;

    public BankAccount(String accountNumber, double balance) {
        this.accountNumber = accountNumber;
        this.balance = balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited $" + amount + " into " + accountNumber + ". New Balance: $" + balance);
        }
    }

    public void displayBalance() {
        System.out.println(accountNumber + " Balance: $" + balance);
    }
}

// SavingsAccount has exactly ONE direct superclass: BankAccount
class SavingsAccount extends BankAccount {
    private double interestRate; // e.g., 0.05 for 5%

    public SavingsAccount(String accountNumber, double balance, double interestRate) {
        super(accountNumber, balance);
        this.interestRate = interestRate;
    }

    public void applyInterest() {
        double interest = balance * interestRate;
        balance += interest;
        System.out.println("Applied interest of $" + interest + ". New Balance: $" + balance);
    }
}

public class BankingDemo {
    public static void main(String[] args) {
        // Instantiate SavingsAccount
        SavingsAccount savings = new SavingsAccount("SAV-4091", 1000.0, 0.05);

        // 1. Inherited methods from BankAccount
        savings.displayBalance();
        savings.deposit(500.0);

        // 2. Specialized method from SavingsAccount
        savings.applyInterest();
        savings.displayBalance();
    }
}

