class Vehicle {
    protected String make;
    protected String model;
    protected int speed;

    public Vehicle(String make, String model) {
        this.make = make;
        this.model = model;
        this.speed = 0;
    }

    public void accelerate(int amount) {
        speed += amount;
        System.out.println(make + " " + model + " accelerated to " + speed + " km/h");
    }

    public void brake() {
        speed = 0;
        System.out.println(make + " " + model + " has stopped.");
    }
}

class ElectricCar extends Vehicle {
    private int batteryPercentage;

    public ElectricCar(String make, String model, int battery) {
        super(make, model);
        this.batteryPercentage = battery;
    }

    public void chargeBattery() {
        this.batteryPercentage = 100;
        System.out.println(make + " " + model + " battery charged to 100%!");
    }
}

public class VehicleDemo {
    public static void main(String[] args) {
        ElectricCar ev = new ElectricCar("Tesla", "Model 3", 65);
        ev.accelerate(80);
        ev.chargeBattery();
        ev.brake();
    }
}

