class Computer {
    String processor;

    void boot() {
        System.out.println("Computer booting with " + processor);
    }
}

class Desktop extends Computer {
    int monitorCount;

    void showMonitors() {
        System.out.println("Desktop connected to " + monitorCount + " monitor(s)");
    }
}

public class Main {
    public static void main(String[] args) {
        Desktop dt = new Desktop();
        dt.processor = "Intel Core i7";
        dt.monitorCount = 2;
        dt.boot();
        dt.showMonitors();
    }
}

