class Order {
    protected String orderId;
    protected double amount;

    public Order(String orderId, double amount) {
        this.orderId = orderId;
        this.amount = amount;
    }

    public double calculateTotal() {
        return amount;
    }

    public void printReceipt() {
        System.out.println("Order: " + orderId + ", Total: $" + calculateTotal());
    }
}

class ExpressOrder extends Order {
    private double expressFee;

    public ExpressOrder(String orderId, double amount, double expressFee) {
        super(orderId, amount);
        this.expressFee = expressFee;
    }

    @Override
    public double calculateTotal() {
        return amount + expressFee;
    }

    public void trackDelivery() {
        System.out.println("Tracking express order " + orderId + " with expedited courier.");
    }
}

public class Main {
    public static void main(String[] args) {
        ExpressOrder order = new ExpressOrder("EXP-9001", 120.0, 15.0);
        order.printReceipt();
        order.trackDelivery();
    }
}
